/// `Ok(None)` means that this stage cannot decide: some point has a weight
/// other than [`Weight::One`], or some coordinate has more than
/// [`MAX_COORD_COMPONENTS`] components or a nonzero component of magnitude
/// outside [`SPANS_TRANSLATED_RANGE`] or not finite.
///
/// Requirement: every coordinate is a valid expansion of `scratch`: nonzero
/// components of strictly increasing magnitude that do not overlap, as
/// [`Point::exact`](implicit_predicates_core::Point::exact) writes them. This
/// is not checked, and the result is unspecified otherwise.
///
/// The arena is left as it was, on success and on error.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[cold]
#[inline(never)]
pub fn expansions_translated_in(
    scratch: &mut Scratch<'_>,
    p: [&ExactCoords; 4],
) -> Result<Option<Sign>, ScratchExhausted> {
    fn evaluate(scratch: &mut Scratch<'_>, c: [[Span; 3]; 4]) -> Result<Sign, ScratchExhausted> {
        let e0 = scratch.diff(c[0][0], c[3][0])?;
        let e1 = scratch.diff(c[0][1], c[3][1])?;
        let e2 = scratch.diff(c[0][2], c[3][2])?;
        let e3 = scratch.diff(c[1][0], c[3][0])?;
        let e4 = scratch.diff(c[1][1], c[3][1])?;
        let e5 = scratch.diff(c[1][2], c[3][2])?;
        let e6 = scratch.diff(c[2][0], c[3][0])?;
        let e7 = scratch.diff(c[2][1], c[3][1])?;
        let e8 = scratch.diff(c[2][2], c[3][2])?;
        let e9 = scratch.product(e4, e8)?;
        let e10 = scratch.product(e5, e7)?;
        let e11 = scratch.diff(e9, e10)?;
        let e12 = scratch.product(e0, e11)?;
        let e13 = scratch.product(e3, e8)?;
        let e14 = scratch.product(e5, e6)?;
        let e15 = scratch.diff(e13, e14)?;
        let e16 = scratch.product(e1, e15)?;
        let e17 = scratch.diff(e12, e16)?;
        let e18 = scratch.product(e3, e7)?;
        let e19 = scratch.product(e4, e6)?;
        let e20 = scratch.diff(e18, e19)?;
        let e21 = scratch.product(e2, e20)?;
        let e22 = scratch.sum(e17, e21)?;
        Ok(scratch.sign(e22))
    }
    // Every coordinate read must be short enough and within the range; the
    // arena is reset to its mark whatever the evaluation returns.
    if !p.iter().all(|q| q.w == Weight::One) {
        return Ok(None);
    }
    let c = p.map(|q| [q.x, q.y, q.z]);
    let coordinates = [
        c[0][0], c[0][1], c[0][2], c[1][0], c[1][1], c[1][2], c[2][0], c[2][1], c[2][2], c[3][0],
        c[3][1], c[3][2],
    ];
    if !coordinates
        .into_iter()
        .all(|s| span_in_range(scratch.get(s), SPANS_TRANSLATED_RANGE))
    {
        return Ok(None);
    }
    let mark = scratch.mark();
    let sign = evaluate(scratch, c);
    scratch.reset(mark);
    sign.map(Some)
}

/// The exact sign of the predicate for points given by their exact coordinates:
/// its form for exact evaluation, marked `#[exact]` in the definition,
/// evaluated with expansions in `scratch` on the coordinates.
///
/// `Ok(None)` means that this stage cannot decide: some point has a weight
/// other than [`Weight::One`], or some coordinate has more than
/// [`MAX_COORD_COMPONENTS`] components or a nonzero component of magnitude
/// outside [`SPANS_UNTRANSLATED_RANGE`] or not finite.
///
/// Requirement: every coordinate is a valid expansion of `scratch`: nonzero
/// components of strictly increasing magnitude that do not overlap, as
/// [`Point::exact`](implicit_predicates_core::Point::exact) writes them. This
/// is not checked, and the result is unspecified otherwise.
///
/// The arena is left as it was, on success and on error.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[cold]
#[inline(never)]
pub fn expansions_untranslated_in(
    scratch: &mut Scratch<'_>,
    p: [&ExactCoords; 4],
) -> Result<Option<Sign>, ScratchExhausted> {
    fn evaluate(scratch: &mut Scratch<'_>, c: [[Span; 3]; 4]) -> Result<Sign, ScratchExhausted> {
        let e3 = scratch.product(c[2][1], c[3][2])?;
        let e6 = scratch.product(c[2][2], c[3][1])?;
        let e7 = scratch.diff(e3, e6)?;
        let e8 = scratch.product(c[1][0], e7)?;
        let e11 = scratch.product(c[2][0], c[3][2])?;
        let e13 = scratch.product(c[2][2], c[3][0])?;
        let e14 = scratch.diff(e11, e13)?;
        let e15 = scratch.product(c[1][1], e14)?;
        let e16 = scratch.diff(e8, e15)?;
        let e18 = scratch.product(c[2][0], c[3][1])?;
        let e19 = scratch.product(c[2][1], c[3][0])?;
        let e20 = scratch.diff(e18, e19)?;
        let e21 = scratch.product(c[1][2], e20)?;
        let e22 = scratch.sum(e16, e21)?;
        let e24 = scratch.product(c[0][0], e7)?;
        let e26 = scratch.product(c[0][1], e14)?;
        let e27 = scratch.diff(e24, e26)?;
        let e29 = scratch.product(c[0][2], e20)?;
        let e30 = scratch.sum(e27, e29)?;
        let e31 = scratch.product(c[1][1], c[3][2])?;
        let e32 = scratch.product(c[1][2], c[3][1])?;
        let e33 = scratch.diff(e31, e32)?;
        let e34 = scratch.product(c[0][0], e33)?;
        let e35 = scratch.product(c[1][0], c[3][2])?;
        let e36 = scratch.product(c[1][2], c[3][0])?;
        let e37 = scratch.diff(e35, e36)?;
        let e38 = scratch.product(c[0][1], e37)?;
        let e39 = scratch.diff(e34, e38)?;
        let e40 = scratch.product(c[1][0], c[3][1])?;
        let e41 = scratch.product(c[1][1], c[3][0])?;
        let e42 = scratch.diff(e40, e41)?;
        let e43 = scratch.product(c[0][2], e42)?;
        let e44 = scratch.sum(e39, e43)?;
        let e45 = scratch.product(c[1][1], c[2][2])?;
        let e46 = scratch.product(c[1][2], c[2][1])?;
        let e47 = scratch.diff(e45, e46)?;
        let e48 = scratch.product(c[0][0], e47)?;
        let e49 = scratch.product(c[1][0], c[2][2])?;
        let e50 = scratch.product(c[1][2], c[2][0])?;
        let e51 = scratch.diff(e49, e50)?;
        let e52 = scratch.product(c[0][1], e51)?;
        let e53 = scratch.diff(e48, e52)?;
        let e54 = scratch.product(c[1][0], c[2][1])?;
        let e55 = scratch.product(c[1][1], c[2][0])?;
        let e56 = scratch.diff(e54, e55)?;
        let e57 = scratch.product(c[0][2], e56)?;
        let e58 = scratch.sum(e53, e57)?;
        let e59 = scratch.push(&[])?;
        let e60 = scratch.diff(e59, e22)?;
        let e61 = scratch.sum(e60, e30)?;
        let e62 = scratch.diff(e61, e44)?;
        let e63 = scratch.sum(e62, e58)?;
        Ok(scratch.sign(e63))
    }
    // Every coordinate read must be short enough and within the range; the
    // arena is reset to its mark whatever the evaluation returns.
    if !p.iter().all(|q| q.w == Weight::One) {
        return Ok(None);
    }
    let c = p.map(|q| [q.x, q.y, q.z]);
    let coordinates = [
        c[0][0], c[0][1], c[0][2], c[1][0], c[1][1], c[1][2], c[2][0], c[2][1], c[2][2], c[3][0],
        c[3][1], c[3][2],
    ];
    if !coordinates
        .into_iter()
        .all(|s| span_in_range(scratch.get(s), SPANS_UNTRANSLATED_RANGE))
    {
        return Ok(None);
    }
    let mark = scratch.mark();
    let sign = evaluate(scratch, c);
    scratch.reset(mark);
    sign.map(Some)
}

/// The sign of the predicate for explicit points, from the first stage that
/// decides.
///
/// Runs [`filter`] with `e = [0.0; 3]`, then [`exact_differences`], then
/// [`expansions_translated`], then [`expansions_untranslated`]. `None` means
/// that no stage can decide.
#[inline]
pub fn staged(p: [&[f64; 3]; 4]) -> Option<Sign> {
    filter(p, [0.0; 3])
        .or_else(|| exact_differences(p))
        .or_else(|| expansions_translated(p))
        .or_else(|| expansions_untranslated(p))
}

/// [`filter`] on the approximations of points of any type, with the uncertainty
/// of their errors: `[0.0; 3]` when every point is explicit, and otherwise
/// `uncertainty` of their errors, from `implicit_predicates_core::filter`.
///
/// The errors are not read when every point is explicit. When that is known
/// from the types, as with `[f64; 3]`, whose `is_explicit` is the constant
/// `true`, this is `filter` with `e = [0.0; 3]`.
#[inline]
pub fn filter_points<P0: Point, P1: Point, P2: Point, P3: Point>(
    p0: &P0,
    p1: &P1,
    p2: &P2,
    p3: &P3,
) -> Option<Sign> {
    let p = [p0.approx(), p1.approx(), p2.approx(), p3.approx()];
    let e = if p0.is_explicit() & p1.is_explicit() & p2.is_explicit() & p3.is_explicit() {
        [0.0; 3]
    } else {
        implicit_predicates_core::filter::uncertainty([p0.err(), p1.err(), p2.err(), p3.err()])
    };
    filter(p, e)
}

/// The exact stages of [`staged`], after its filter: [`exact_differences`],
/// then [`expansions_translated`], then [`expansions_untranslated`]. `None`
/// means that no stage can decide.
#[cold]
#[inline(never)]
pub fn exact_stages(p: [&[f64; 3]; 4]) -> Option<Sign> {
    exact_differences(p)
        .or_else(|| expansions_translated(p))
        .or_else(|| expansions_untranslated(p))
}

/// The exact sign of the predicate for points of any type:
/// [`expansions_translated_in`], then [`expansions_untranslated_in`], on the
/// exact coordinates of the points written to `scratch`, which is reset to its
/// mark whatever they return. `Ok(None)` means that no stage can decide: the
/// inputs of some point are outside the range of its exact arithmetic
/// ([`ExactError::OutOfRange`]), or none of the stages decides.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[cold]
#[inline(never)]
pub fn exact_stages_in<P0: Point, P1: Point, P2: Point, P3: Point>(
    scratch: &mut Scratch<'_>,
    p0: &P0,
    p1: &P1,
    p2: &P2,
    p3: &P3,
) -> Result<Option<Sign>, ScratchExhausted> {
    fn run<P0: Point, P1: Point, P2: Point, P3: Point>(
        scratch: &mut Scratch<'_>,
        p0: &P0,
        p1: &P1,
        p2: &P2,
        p3: &P3,
    ) -> Result<Option<Sign>, ScratchExhausted> {
        let Some(q0) = exact(scratch, p0)? else {
            return Ok(None);
        };
        let Some(q1) = exact(scratch, p1)? else {
            return Ok(None);
        };
        let Some(q2) = exact(scratch, p2)? else {
            return Ok(None);
        };
        let Some(q3) = exact(scratch, p3)? else {
            return Ok(None);
        };
        let q = [&q0, &q1, &q2, &q3];
        if let Some(sign) = expansions_translated_in(scratch, q)? {
            return Ok(Some(sign));
        }
        expansions_untranslated_in(scratch, q)
    }
    let mark = scratch.mark();
    let result = run(scratch, p0, p1, p2, p3);
    scratch.reset(mark);
    result
}

/// The sign of the predicate for points of any type, from the first stage that
/// decides.
///
/// Runs [`filter_points`]; then, when every point is explicit, [`exact_stages`]
/// on their coordinates, which does not use `scratch`; otherwise
/// [`exact_stages_in`], on their exact coordinates written to `scratch`.
/// `scratch` is left as it was. `Ok(None)` means that no stage can decide.
///
/// # Errors
///
/// [`ScratchExhausted`] if `scratch` runs out of room.
#[inline]
pub fn staged_in<P0: Point, P1: Point, P2: Point, P3: Point>(
    scratch: &mut Scratch<'_>,
    p0: &P0,
    p1: &P1,
    p2: &P2,
    p3: &P3,
) -> Result<Option<Sign>, ScratchExhausted> {
    if let Some(sign) = filter_points(p0, p1, p2, p3) {
        return Ok(Some(sign));
    }
    if p0.is_explicit() & p1.is_explicit() & p2.is_explicit() & p3.is_explicit() {
        return Ok(exact_stages([
            p0.approx(),
            p1.approx(),
            p2.approx(),
            p3.approx(),
        ]));
    }
    exact_stages_in(scratch, p0, p1, p2, p3)
}

/// The exact coordinates of the point `p`, written to `scratch`, or `None` if
/// its inputs are outside the range of its exact arithmetic.
fn exact(
    scratch: &mut Scratch<'_>,
    p: &impl Point,
) -> Result<Option<ExactCoords>, ScratchExhausted> {
    match p.exact(scratch) {
        Ok(c) => Ok(Some(c)),
        Err(ExactError::OutOfRange) => Ok(None),
        Err(ExactError::Exhausted(e)) => Err(e),
    }
}

/// The larger of `a` and `b`, or `b` if they are unordered.
#[inline]
fn max(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

/// Whether `x` is zero or has a magnitude in `min..=max`; false for NaN and
/// infinities.
fn in_range(x: f64, (min, max): (f64, f64)) -> bool {
    x == 0.0 || (min..=max).contains(&x.abs())
}

/// Whether the expansion `e` has at most [`MAX_COORD_COMPONENTS`] components,
/// each zero or of a magnitude in `min..=max`.
fn span_in_range(e: &[f64], range: (f64, f64)) -> bool {
    e.len() <= MAX_COORD_COMPONENTS && e.iter().all(|&x| in_range(x, range))
}

/// Writes the expansion of `x * y` to `out` and returns its length: the sum of
/// the scalings of `y` by each component of `x`, each scaling written to
/// `scaled`, the partial sums alternating between `spare` and `out`.
fn product(x: &[f64], y: &[f64], scaled: &mut [f64], spare: &mut [f64], out: &mut [f64]) -> usize {
    let Some((&first, rest)) = x.split_first() else {
        return 0;
    };
    // Start so that the last partial sum is written to `out`.
    let (mut partial, mut next) = if rest.len() % 2 == 0 {
        (out, spare)
    } else {
        (spare, out)
    };
    let mut length = expansion::scale(y, first, partial);
    for &component in rest {
        let scaled_length = expansion::scale(y, component, scaled);
        length = expansion::sum(&partial[..length], &scaled[..scaled_length], next);
        core::mem::swap(&mut partial, &mut next);
    }
    length
}
